const crypto = require('crypto');

// Generate internal UUID and human-readable Tracking Number
const inquiry_id = `inq_${crypto.randomUUID()}`;
const date = new Date();
const yyyy = date.getFullYear();
const mm = String(date.getMonth() + 1).padStart(2, '0');
const dd = String(date.getDate()).padStart(2, '0');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const tracking_number = `TRK-${yyyy}${mm}${dd}-${randomSuffix}`;

const item = $input.first().json;
const fromEmail = item.from?.value?.[0]?.address || item.from || 'customer@example.com';
const fromName = item.from?.value?.[0]?.name || item.senderName || 'Valued Customer';
const subject = item.subject || 'Inquiry';
const bodyText = item.textPlain || item.snippet || item.body || '';
const threadId = item.threadId || item.id || '';

return [{
  json: {
    inquiry_id,
    tracking_number,
    customer_email: fromEmail,
    customer_name: fromName,
    subject,
    body: bodyText,
    thread_id: threadId,
    timestamp: date.toISOString()
  }
}];

const rawAi = $input.first().json;
let parsed = {};

try {
  const content = rawAi.message?.content || rawAi.text || rawAi;
  parsed = typeof content === 'string' ? JSON.parse(content.replace(/```json/gi, '').replace(/```/g, '').trim()) : content;
} catch (e) {
  parsed = {
    is_sensitive: false,
    sensitivity_reason: null,
    primary_intent: 'Complaint',
    secondary_intent: 'other',
    inquiry_category: 'other',
    services_requested: [],
    missing_required_info: ['vehicle_details', 'service_details'],
    customer_sentiment: 'neutral',
    ai_summary: 'Manual review required due to AI schema parse fallback.'
  };
}

// Secondary deterministic regex safety filter for sensitivity
const bodyText = ($('Idempotency & Format Input').item.json.subject + ' ' + $('Idempotency & Format Input').item.json.body).toLowerCase();
const sensitiveKeywords = ['refund', 'refund request', 'chargeback', 'dispute', 'payment dispute', 'serious payment dispute', 'attorney', 'lawyer', 'lawsuit', 'legal action', 'legal threat', 'sue', 'court', 'bbb', 'better business bureau', 'consumer protection', 'regulatory complaint', 'attorney general', 'damage', 'damaged my car', 'fraud', 'scam', 'stolen', 'threat', 'negligence'];

let is_sensitive = Boolean(parsed.is_sensitive);
let sensitivity_reason = parsed.sensitivity_reason || null;

for (const kw of sensitiveKeywords) {
  if (bodyText.includes(kw)) {
    is_sensitive = true;
    if (!sensitivity_reason) sensitivity_reason = `Matched safety trigger: "${kw}"`;
    break;
  }
}

let primary_intent = parsed.primary_intent || (is_sensitive ? 'Complaint' : 'Sales');
if (is_sensitive && primary_intent !== 'Payment') primary_intent = 'Complaint';
const secondary_intent = parsed.secondary_intent || parsed.inquiry_category || 'general_inquiry';

const vehicle = parsed.vehicle || {};
const hasVehicle = Boolean(vehicle.year && vehicle.make && vehicle.model);
const hasServices = Array.isArray(parsed.services_requested) && parsed.services_requested.length > 0;
const missing_info = (!hasVehicle || !hasServices || (parsed.missing_required_info && parsed.missing_required_info.length > 0));

return [{
  json: {
    ...$('Idempotency & Format Input').item.json,
    hubspot_ticket_id: $('HubSpot: Create Support Ticket (First Invariant)').item.json.id,
    ai: {
      ...parsed,
      primary_intent,
      secondary_intent
    },
    is_sensitive,
    sensitivity_reason,
    missing_info,
    vehicle,
    services_requested: parsed.services_requested || []
  }
}];

// Deterministic Pricing Calculation Matrix
const PRICING_MATRIX = {
  'oil_change_synthetic': { rates: { 'tier_1_sedan_coupe': 79.95, 'tier_2_suv_crossover': 94.95, 'tier_3_truck_van_diesel': 119.95 } },
  'oil_change_diesel': { rates: { 'tier_3_truck_van_diesel': 189.95 } },
  'brake_pads_front': { rates: { 'tier_1_sedan_coupe': 189.00, 'tier_2_suv_crossover': 219.00, 'tier_3_truck_van_diesel': 269.00 } },
  'brake_pads_rotors_front': { rates: { 'tier_1_sedan_coupe': 349.00, 'tier_2_suv_crossover': 419.00, 'tier_3_truck_van_diesel': 499.00 } },
  'tire_rotation': { rates: { 'tier_1_sedan_coupe': 29.95, 'tier_2_suv_crossover': 29.95, 'tier_3_truck_van_diesel': 39.95 } },
  'coolant_flush': { rates: { 'tier_1_sedan_coupe': 149.95, 'tier_2_suv_crossover': 169.95, 'tier_3_truck_van_diesel': 199.95 } },
  'transmission_flush': { rates: { 'tier_1_sedan_coupe': 229.00, 'tier_2_suv_crossover': 259.00, 'tier_3_truck_van_diesel': 299.00 } },
  'ac_recharge_r134a': { rates: { 'tier_1_sedan_coupe': 169.00, 'tier_2_suv_crossover': 189.00, 'tier_3_truck_van_diesel': 219.00 } },
  'diagnostic_fee': { rates: { 'tier_1_sedan_coupe': 149.00, 'tier_2_suv_crossover': 149.00, 'tier_3_truck_van_diesel': 149.00 } }
};

const item = $input.first().json;
const vehicle = item.vehicle || {};
const tier = vehicle.tier_guess || 'unknown';

if (tier === 'unknown' || tier === 'unknown_manual' || tier === 'tier_4_exotic_commercial') {
  return [{
    json: {
      ...item,
      pricing_status: 'manual_quote_required',
      estimated_cost: null,
      vehicle_tier: tier
    }
  }];
}

let total = 0;
let requiresManual = false;

for (const s of (item.services_requested || [])) {
  const clean = s.toLowerCase();
  let key = null;
  if (clean.includes('rotors') || clean.includes('pads and rotors')) key = 'brake_pads_rotors_front';
  else if (clean.includes('brake')) key = 'brake_pads_front';
  else if (clean.includes('diesel oil')) key = 'oil_change_diesel';
  else if (clean.includes('oil')) key = 'oil_change_synthetic';
  else if (clean.includes('tire') || clean.includes('rotation')) key = 'tire_rotation';
  else if (clean.includes('coolant')) key = 'coolant_flush';
  else if (clean.includes('transmission')) key = 'transmission_flush';
  else if (clean.includes('ac') || clean.includes('air conditioning')) key = 'ac_recharge_r134a';
  else if (clean.includes('diagnostic')) key = 'diagnostic_fee';

  if (key && PRICING_MATRIX[key]?.rates?.[tier]) {
    total += PRICING_MATRIX[key].rates[tier];
  } else {
    requiresManual = true;
  }
}

return [{
  json: {
    ...item,
    pricing_status: requiresManual ? 'manual_quote_required' : 'quoted_automatically',
    estimated_cost: requiresManual ? null : parseFloat(total.toFixed(2)),
    vehicle_tier: tier
  }
}];
